tests.command:
node --input-type=module - <<'NODE'
import { resolve } from 'node:path';
import { build } from 'vite';
const root = resolve('experiments/orbital-mechanics/luna-max-minimal');
const result = await build({ root, configFile: false, logLevel: 'warn', build: { write: false, emptyOutDir: false } });
const builds = Array.isArray(result) ? result : [result];
for (const output of builds) console.log(`Vite isolated build: ${output.output?.length ?? 0} output entries; write:false; root=${root}`);
NODE
